{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

/*
 * TodoMVC — vanilla JS implementation.
 *
 * Drives the markup in index.html. State lives in localStorage under
 * `todos-vanilla`; the active filter is persisted under `todos-vanilla-filter`
 * so it survives a reload (required by the filter-route scenarios).
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var FILTER_KEY = 'todos-vanilla-filter';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var app = {
    todos: [],
    filter: 'all',
  };

  var newTodoInput;
  var main;
  var footer;
  var list;
  var toggleAll;
  var clearCompleted;
  var countEl;
  var filterLinks;

  // @planks(
  //   "the app has loaded with an empty todo list",
  //   "the todo list contains the items:"
  // )
  function load() {
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      app.todos = raw ? JSON.parse(raw) : [];
    } catch (e) {
      app.todos = [];
    }
  }

  // @planks(
  //   "I enter {string} into the new todo input and press Enter",
  //   "the todo list contains the items:",
  //   "I toggle the checkbox of the item {string}",
  //   "I toggle the mark-all checkbox",
  //   "I click the destroy button for the item {string}",
  //   "I set the edit input to {string} and press Enter",
  //   "I set the edit input to {string} and blur it",
  //   "I click the clear-completed button",
  //   "the app persists the todos"
  // )
  function save() {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(app.todos));
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  function findById(id) {
    for (var i = 0; i < app.todos.length; i++) {
      if (String(app.todos[i].id) === String(id)) return app.todos[i];
    }
    return null;
  }

  function activeCount() {
    return app.todos.filter(function (t) { return !t.completed; }).length;
  }

  // @planks(
  //   "the visible todo list contains {int} items",
  //   "I navigate to {string}",
  //   "the item {string} is not visible",
  //   "the item {string} is visible"
  // )
  function currentFilter() {
    var hash = window.location.hash;
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    // An explicit All-route hash wins over any persisted filter: the route
    // the address bar shows right now is authoritative.
    if (hash === '#/') return 'all';
    // An empty hash (reload / initial load) restores the persisted filter.
    var persisted = window.localStorage.getItem(FILTER_KEY);
    if (persisted === '#/active') return 'active';
    if (persisted === '#/completed') return 'completed';
    return 'all';
  }

  // @planks(
  //   "the todo list contains {int} items",
  //   "the item at position {int} has the title {string}",
  //   "the item at position {int} is not completed",
  //   "the item {string} is completed",
  //   "the list item for {string} has the {string} class",
  //   "the list item for {string} does not have the {string} class",
  //   "every item is completed",
  //   "the mark-all checkbox is checked",
  //   "the mark-all checkbox is not checked",
  //   "the todo count is {int}",
  //   "the todo count reads {string}",
  //   "the clear-completed button is hidden",
  //   "the item {string} is present",
  //   "the item {string} is absent",
  //   "the main section is visible",
  //   "the main section is hidden",
  //   "the footer is visible",
  //   "the footer is hidden",
  //   "the filter link {string} has the {string} class",
  //   "the filter link {string} does not have the {string} class"
  // )
  function render() {
    var seen = {};
    app.todos.forEach(function (todo) {
      var id = String(todo.id);
      seen[id] = true;
      var li = list.querySelector('.todo[data-id="' + id + '"]');
      if (!li) {
        li = document.createElement('li');
        li.dataset.id = id;

        var view = document.createElement('div');
        view.className = 'view';

        var toggle = document.createElement('input');
        toggle.type = 'checkbox';
        toggle.className = 'toggle';

        var label = document.createElement('label');

        var destroy = document.createElement('button');
        destroy.className = 'destroy';

        view.appendChild(toggle);
        view.appendChild(label);
        view.appendChild(destroy);

        var edit = document.createElement('input');
        edit.className = 'edit';

        li.appendChild(view);
        li.appendChild(edit);
        list.appendChild(li);
      }
      // Update in place so a re-render preserves unchanged item nodes.
      li.className = 'todo' + (todo.completed ? ' completed' : '');
      li.querySelector('.view label').textContent = todo.title;
      li.querySelector('.edit').value = todo.title;
      li.querySelector('.toggle').checked = !!todo.completed;
      // Editing is transient view state; a render returns the item to rest.
      li.querySelector('.view').hidden = false;
      li.querySelector('.edit').hidden = true;
    });

    // Drop nodes whose todo no longer exists.
    Array.prototype.forEach.call(list.querySelectorAll('.todo'), function (li) {
      if (!seen[li.dataset.id]) list.removeChild(li);
    });

    var active = activeCount();
    var completed = app.todos.length - active;
    var hasTodos = app.todos.length > 0;

    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    countEl.innerHTML =
      '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';

    toggleAll.checked = hasTodos && active === 0;
    clearCompleted.hidden = completed === 0;

    Array.prototype.forEach.call(list.children, function (li) {
      var todo = findById(li.dataset.id);
      if (!todo) return;
      var show =
        app.filter === 'all' ||
        (app.filter === 'active' && !todo.completed) ||
        (app.filter === 'completed' && todo.completed);
      li.hidden = !show;
    });

    Array.prototype.forEach.call(filterLinks, function (a) {
      var href = a.getAttribute('href');
      var match =
        (href === '#/' && app.filter === 'all') ||
        (href === '#/active' && app.filter === 'active') ||
        (href === '#/completed' && app.filter === 'completed');
      if (match) a.classList.add('selected');
      else a.classList.remove('selected');
    });

    save();
  }

  // @planks("I enter {string} into the new todo input and press Enter")
  function onNewTodoKey(e) {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      var title = newTodoInput.value.trim();
      if (title !== '') {
        app.todos.push({ id: uid(), title: title, completed: false });
        newTodoInput.value = '';
        save();
        render();
      }
    }
  }

  // @planks("I toggle the checkbox of the item {string}")
  function onListChange(e) {
    if (!e.target.classList.contains('toggle')) return;
    var li = e.target.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    todo.completed = e.target.checked;
    save();
    render();
  }

  // @planks("I toggle the mark-all checkbox")
  function onToggleAll() {
    var allCompleted = toggleAll.checked;
    app.todos.forEach(function (t) { t.completed = allCompleted; });
    save();
    render();
  }

  // @planks("I click the destroy button for the item {string}")
  function onListClick(e) {
    var destroy = e.target.closest('.destroy');
    if (!destroy) return;
    var li = destroy.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    app.todos = app.todos.filter(function (t) { return String(t.id) !== String(todo.id); });
    save();
    render();
  }

  // @planks("I double-click the label of the item {string}")
  function onListDblClick(e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    li.classList.add('editing');
    var view = li.querySelector('.view');
    var edit = li.querySelector('.edit');
    edit.value = todo.title;
    // Edit mode hides the item's view controls and shows the edit input.
    view.hidden = true;
    edit.hidden = false;
    edit.focus();
  }

  function commitEdit(edit) {
    var li = edit.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    var title = edit.value.trim();
    if (title === '') {
      app.todos = app.todos.filter(function (t) { return String(t.id) !== String(todo.id); });
    } else {
      todo.title = title;
    }
    save();
    render();
  }

  function cancelEdit(edit) {
    var li = edit.closest('.todo');
    var todo = findById(li.dataset.id);
    if (todo) edit.value = todo.title;
    li.classList.remove('editing');
    li.querySelector('.view').hidden = false;
    li.querySelector('.edit').hidden = true;
    edit.blur();
  }

  // @planks(
  //   "I set the edit input to {string} and press Enter",
  //   "I set the edit input to {string} and blur it",
  //   "I press Escape in the edit input"
  // )
  function onListKey(e) {
    if (!e.target.classList.contains('edit')) return;
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) commitEdit(e.target);
    else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) cancelEdit(e.target);
  }

  // @planks("I set the edit input to {string} and blur it")
  function onListBlur(e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('.todo');
    if (li && li.classList.contains('editing')) commitEdit(e.target);
  }

  // @planks("I navigate to {string}")
  function onRoute() {
    app.filter = currentFilter();
    if (window.location.hash === '#/active' || window.location.hash === '#/completed') {
      window.localStorage.setItem(FILTER_KEY, window.location.hash);
    }
    render();
  }

  // @planks("I click the clear-completed button")
  function onClearCompleted() {
    app.todos = app.todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function init() {
    newTodoInput = document.querySelector('.new-todo');
    main = document.querySelector('.main');
    footer = document.querySelector('.footer');
    list = document.querySelector('.todo-list');
    toggleAll = document.querySelector('.toggle-all');
    clearCompleted = document.querySelector('.clear-completed');
    countEl = document.querySelector('.todo-count');
    filterLinks = document.querySelectorAll('.filters a');

    load();
    app.filter = currentFilter();

    window.addEventListener('hashchange', onRoute);
    newTodoInput.addEventListener('keydown', onNewTodoKey);
    toggleAll.addEventListener('change', onToggleAll);
    list.addEventListener('change', onListChange);
    list.addEventListener('click', onListClick);
    list.addEventListener('dblclick', onListDblClick);
    list.addEventListener('keydown', onListKey);
    list.addEventListener('blur', onListBlur, true);
    clearCompleted.addEventListener('click', onClearCompleted);

    render();

    // Expose a narrow persistence hook for the schema-conformance step.
    window.todoApp = { save: save };
  }

  init();
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp(seed) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // A reload re-seeds the fresh window with the previous window's localStorage so that
    // persisted todos and the persisted route survive the window teardown/rebuild.
    if (seed) {
      for (const [k, v] of Object.entries(seed)) this.window.localStorage.setItem(k, v);
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }

  // Capture the current window's localStorage so a reload can rebuild the next window with it.
  snapshotLocalStorage() {
    const seed = {};
    const w = this.window;
    if (w && w.localStorage) {
      for (let i = 0; i < w.localStorage.length; i++) {
        const k = w.localStorage.key(i);
        seed[k] = w.localStorage.getItem(k);
      }
    }
    return seed;
  }

  // Tear down the current window and build a fresh one, preserving localStorage (todos + route).
  reloadApp() {
    const seed = this.snapshotLocalStorage();
    this.disposeApp();
    this.loadApp(seed);
    return this.document;
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const fs = require('node:fs');
const path = require('node:path');
const { Given, When, Then } = require('@cucumber/cucumber');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const STORAGE_KEY = 'todos-vanilla';
const FILTER_KEY = 'todos-vanilla-filter';

// --- DOM helpers ---------------------------------------------------------

function doc(world) {
  return world.document;
}

function allItems(document) {
  return Array.from(document.querySelectorAll('.todo-list .todo'));
}

function itemByTitle(document, title) {
  return allItems(document).find((li) => {
    const label = li.querySelector('.view label');
    return label && label.textContent.trim() === title;
  });
}

function visibleItems(document) {
  return allItems(document).filter((li) => !li.hidden);
}

function filterLink(document, name) {
  return Array.from(document.querySelectorAll('.filters a')).find(
    (a) => a.textContent.trim() === name,
  );
}

// --- Background / fixtures ----------------------------------------------

Given('the app has loaded with an empty todo list', function () {
  this.window.localStorage.removeItem(STORAGE_KEY);
  this.window.localStorage.removeItem(FILTER_KEY);
  this.reloadApp();
});

Given('the todo list contains the items:', function (dataTable) {
  const rows = dataTable.hashes();
  const items = rows.map((r, i) => ({
    id: String(i + 1),
    title: r.title,
    completed: r.completed === 'true',
  }));
  this.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  this.reloadApp();
});

// --- Creating -----------------------------------------------------------

When('I enter {string} into the new todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Then(/^the todo list contains (\d+) items?$/, function (n) {
  const got = allItems(this.document).length;
  if (got !== Number(n)) throw new Error(`expected ${n} items, found ${got}`);
});

Then('the item at position {int} has the title {string}', function (pos, title) {
  const items = allItems(this.document);
  const li = items[pos - 1];
  if (!li) throw new Error(`no item at position ${pos} (have ${items.length})`);
  const got = li.querySelector('.view label').textContent.trim();
  if (got !== title) throw new Error(`item at position ${pos} is "${got}", expected "${title}"`);
});

Then('the item at position {int} is not completed', function (pos) {
  const li = allItems(this.document)[pos - 1];
  if (!li) throw new Error(`no item at position ${pos}`);
  if (li.classList.contains('completed')) throw new Error(`item at position ${pos} is completed`);
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') throw new Error(`new todo input is "${input.value}", expected empty`);
});

Then('the main section is visible', function () {
  if (this.document.querySelector('.main').hidden) throw new Error('main section is hidden');
});

Then('the main section is hidden', function () {
  if (!this.document.querySelector('.main').hidden) throw new Error('main section is visible');
});

Then('the footer is visible', function () {
  if (this.document.querySelector('.footer').hidden) throw new Error('footer is hidden');
});

Then('the footer is hidden', function () {
  if (!this.document.querySelector('.footer').hidden) throw new Error('footer is visible');
});

// --- Toggling / completing ---------------------------------------------

When('I toggle the checkbox of the item {string}', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Then('the item {string} is completed', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (!li.classList.contains('completed')) throw new Error(`item "${title}" is not completed`);
});

Then('the item {string} is not completed', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (li.classList.contains('completed')) throw new Error(`item "${title}" is completed`);
});

Then('the list item for {string} has the {string} class', function (title, klass) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (!li.classList.contains(klass)) throw new Error(`item "${title}" lacks class "${klass}"`);
});

Then('the list item for {string} does not have the {string} class', function (title, klass) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (li.classList.contains(klass)) throw new Error(`item "${title}" still has class "${klass}"`);
});

When('I toggle the mark-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  toggleAll.checked = !toggleAll.checked;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Then('every item is completed', function () {
  const items = allItems(this.document);
  if (items.length === 0) throw new Error('no items to check');
  for (const li of items) {
    if (!li.classList.contains('completed')) throw new Error(`item "${li.querySelector('.view label').textContent.trim()}" is not completed`);
  }
});

Then('the mark-all checkbox is checked', function () {
  if (!this.document.querySelector('.toggle-all').checked) throw new Error('mark-all checkbox is not checked');
});

Then('the mark-all checkbox is not checked', function () {
  if (this.document.querySelector('.toggle-all').checked) throw new Error('mark-all checkbox is checked');
});

// --- Counter ------------------------------------------------------------

Then('the todo count is {int}', function (n) {
  const strong = this.document.querySelector('.todo-count strong');
  if (!strong) throw new Error('no todo-count strong element');
  if (strong.textContent.trim() !== String(n)) throw new Error(`count is "${strong.textContent.trim()}", expected ${n}`);
});

Then('the todo count reads {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  const got = count.textContent.replace(/\s+/g, ' ').trim();
  if (got !== text) throw new Error(`count reads "${got}", expected "${text}"`);
});

// --- Clear completed / destroy -----------------------------------------

When('I click the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('no clear-completed button');
  btn.click();
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('no clear-completed button');
  if (!btn.hidden) throw new Error('clear-completed button is visible');
});

When('I click the destroy button for the item {string}', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const btn = li.querySelector('.destroy');
  if (!btn) throw new Error(`no destroy button for "${title}"`);
  btn.click();
});

Then('the item {string} is present', function (title) {
  if (!itemByTitle(this.document, title)) throw new Error(`item "${title}" is absent`);
});

Then('the item {string} is absent', function (title) {
  if (itemByTitle(this.document, title)) throw new Error(`item "${title}" is present`);
});

// --- Editing ------------------------------------------------------------

When('I double-click the label of the item {string}', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

Then('the edit input for {string} is focused', function (title) {
