function typeMatches(type, value) {
  if (Array.isArray(type)) return type.some((t) => typeMatches(t, value));
  switch (type) {
    case 'string': return typeof value === 'string';
    case 'boolean': return typeof value === 'boolean';
    case 'number': return typeof value === 'number' && !Number.isNaN(value);
    case 'integer': return typeof value === 'number' && Number.isInteger(value);
    case 'array': return Array.isArray(value);
    case 'object': return value !== null && typeof value === 'object' && !Array.isArray(value);
    default: return false;
  }
}

function assertConforms(record, schema, key) {
  if (schema.type && schema.type !== 'array') {
    throw new Error(`schema root type is "${schema.type}", expected "array"`);
  }
  if (!Array.isArray(record)) throw new Error(`localStorage "${key}" is not an array`);
  const itemSchema = schema.items || {};
  const required = itemSchema.required || [];
  const props = itemSchema.properties || {};
  record.forEach((item, i) => {
    if (typeof item !== 'object' || item === null || Array.isArray(item)) {
      throw new Error(`item ${i} is not an object`);
    }
    for (const k of required) {
      if (!(k in item)) throw new Error(`item ${i} is missing required key "${k}"`);
    }
    for (const [k, def] of Object.entries(props)) {
      if (k in item && !typeMatches(def.type, item[k])) {
        throw new Error(`item ${i} key "${k}" has wrong type (expected ${JSON.stringify(def.type)})`);
      }
    }
  });
}

